      BrowserWindow,
      ipcMain,
      safeStorage,
      profile: activeProfile,
      protocolSession: defaultSession,
      dataDir: getAgentDataDir(),
      workspaceRuntimeOptions: {
        packaged: app.isPackaged === true,
