    if (settings.startAntAtLaunch) {
      startAnt();
    }
    if (settings.startIpfsAtLaunch) {
      startIpfs();
    }
    if (settings.enableRadicleIntegration && settings.startRadicleAtLaunch) {
      startRadicle();
    }
