  // ant-data/. Must run before the Ant node is started below, or antd
  // self-generates a throwaway identity on the empty directory.
  migrateBeeDataToAntData();

  const defaultSession = session.defaultSession;
  await defaultSession.clearCache();
  registerBaseIpcHandlers({
    onSetTitle: setWindowTitle,
    onNewWindow: createMainWindow,
    onNewPrivateWindow: createPrivateWindow,
  });
  registerSettingsIpc();
  registerAdblockIpc();
  registerShortcutsIpc();
  registerBookmarksIpc();
  registerHistoryIpc();
  registerDownloadsIpc();
  automationController.setDownloadController({
    download: ({ pageAdapter, ref, conversationId, signal, onProgress }) =>
      runControlledDownload({
        pageAdapter,
        conversationId,
        signal,
        onProgress,
        trigger: () => pageAdapter.download(ref),
      }),
    list: listAgentDownloads,
  });
  automationController.setUploadController(
    createAgentFileUploadController({
      dialog,
      getOwnerWindow: (webContents) =>
        webContents.getOwnerBrowserWindow?.() || BrowserWindow.fromWebContents(webContents),
    })
  );
  registerFaviconsIpc();
  registerEnsIpc();
  registerTezosDomainsIpc();
  registerAntIpc();
  registerIpfsIpc();
  myotisManager.registerMyotisIpc();
  registerRadicleIpc();
  registerTorIpc();
  registerGithubBridgeIpc();
  registerServiceRegistryIpc();
  registerIdentityIpc();
  registerQuickUnlockIpc();
  registerWalletIpc();
  registerLedgerIpc();
  registerRemoteSignerIpc();

