  // pick that up here so this process rebuilds its native Profiles menu and
  // refreshes its renderers, keeping every window's profile list in sync.
  if (
    !RUNTIME_MODE &&
    !TEST_MODE &&
    activeProfile?.source === 'catalog' &&
    activeProfile?.appRoot
