import unittest
from types import SimpleNamespace
from watchdog import authorize_scope,campaign_cases,APPROVED_REQUEST,APPROVED_CASES
class Tests(unittest.TestCase):
 def test_only_ordered_three(self):
  self.assertEqual(APPROVED_CASES,('quit-running','main-loss','supervisor-loss'))
  r=dict(executionReady=True,cases=list(APPROVED_CASES),request=APPROVED_REQUEST)
  authorize_scope(APPROVED_CASES,APPROVED_REQUEST,r)
  for bad in [('quit-idle',),tuple(reversed(APPROVED_CASES)),APPROVED_CASES[:2],APPROVED_CASES+('quit-detached',)]:
   with self.assertRaises(AssertionError):authorize_scope(bad,APPROVED_REQUEST,r)
  with self.assertRaises(AssertionError):authorize_scope(APPROVED_CASES,'wrong',r)
  with self.assertRaises(AssertionError):authorize_scope(APPROVED_CASES,APPROVED_REQUEST,dict(r,executionReady=False))
 def test_stop_first_failure_no_retry(self):
  for failed in (0,1,2,None):
   calls=[]
   def factory(name,_):
    index=len(calls);calls.append(name);return SimpleNamespace(run=lambda:dict(passed=index!=failed))
   rows=campaign_cases('/mock',factory,lambda:0,lambda _:None)
   n=3 if failed is None else failed+1
   self.assertEqual(calls,list(APPROVED_CASES[:n]));self.assertEqual(len(rows),n)
 def test_total_reserve(self):
  times=iter([0,60_000_000_000])
  with self.assertRaises(AssertionError):campaign_cases('/mock',lambda *_:self.fail('must not launch'),lambda:next(times),lambda _:None)
