class BSD(c.Structure):
    _fields_ = [(n, c.c_uint32) for n in ['flags', 'status', 'xstatus', 'pid', 'ppid', 'uid', 'gid', 'ruid', 'rgid', 'svuid', 'svgid', 'reserved']] + [('comm', c.c_char*16), ('name', c.c_char*32)] + [(n, c.c_uint32) for n in ['nfiles', 'pgid', 'jobc', 'tdev', 'tpgid']] + [('nice', c.c_int32), ('seconds', c.c_uint64), ('micros', c.c_uint64)]


class NativeError(RuntimeError):
    def __init__(self, syscall, rc, errno, phase, pid, detail):
        self.evidence = dict(syscall=syscall, rc=rc, errno=errno, phase=phase, pid=pid, detail=detail)
        super().__init__(str(self.evidence))


class Native:
    def __init__(self):
        assert c.sizeof(BSD) == 136
        self.lib = c.CDLL('/usr/lib/libproc.dylib', use_errno=True)
        self.sys = c.CDLL('/usr/lib/libSystem.B.dylib', use_errno=True)
        self.lib.proc_pidinfo.argtypes = [c.c_int, c.c_int, c.c_uint64, c.c_void_p, c.c_int]
        self.lib.proc_listchildpids.argtypes = [c.c_int, c.c_void_p, c.c_int]
        self.lib.proc_pidpath.argtypes = [c.c_int, c.c_void_p, c.c_uint32]
        self.lib.proc_signal_with_audittoken.argtypes = [c.c_void_p, c.c_int]
        self.sys.sysctl.argtypes = [c.POINTER(c.c_int), c.c_uint, c.c_void_p, c.POINTER(c.c_size_t), c.c_void_p, c.c_size_t]
        self.sys.task_name_for_pid.argtypes = [c.c_uint, c.c_int, c.POINTER(c.c_uint)]
        self.sys.task_info.argtypes = [c.c_uint, c.c_int, c.c_void_p, c.POINTER(c.c_uint)]
        self.sys.mach_port_deallocate.argtypes = [c.c_uint, c.c_uint]
        self.self_port = c.c_uint.in_dll(self.sys, 'mach_task_self_').value
        self.kq = select.kqueue(); self.entries = {}; self.events = {}; self._tokens = {}

    def info(self, pid, parent, phase):
        b = BSD(); c.set_errno(0)
        rc = self.lib.proc_pidinfo(pid, 3, 0, c.byref(b), c.sizeof(b)); err = c.get_errno()
        if rc != 136 or b.pid != pid or b.ppid != parent or b.uid != os.getuid():
            raise NativeError('proc_pidinfo', rc, err, phase, pid, 'identity/bytecount mismatch')
        return dict(pid=pid, parent=parent, uid=b.uid, startSeconds=b.seconds, startMicros=b.micros, pgid=b.pgid)

    def argv(self, pid):
        mib = (c.c_int*3)(1, 49, pid); buf = c.create_string_buffer(65536); size = c.c_size_t(len(buf)); c.set_errno(0)
        rc = self.sys.sysctl(mib, 3, buf, c.byref(size), None, 0)
        if rc or not 4 <= size.value <= len(buf):
            raise NativeError('sysctl(KERN_PROCARGS2)', rc, c.get_errno(), 'argv', pid, 'read/size')
        try:
            raw = buf.raw[:size.value]; argc = struct.unpack_from('i', raw)[0]
            assert 1 <= argc <= 256
            at = raw.index(b'\0', 4)+1
            while at < len(raw) and raw[at] == 0: at += 1
            args = []
            for _ in range(argc):
                end = raw.index(b'\0', at); args.append(raw[at:end].decode()); at = end+1
            return args
        except (ValueError, AssertionError, UnicodeError) as e:
            raise NativeError('sysctl(KERN_PROCARGS2)', rc, 0, 'argv-decode', pid, str(e)) from e

    def executable(self, pid):
